    public List<ReportFulfilledShipmentsMongoDTO> performJoinAndFilter2(String specifiedId, int size) {
        MatchOperation matchStage = Aggregation.match(Criteria.where("_id").gt(new ObjectId(specifiedId)));

        LookupOperation lookupStage = LookupOperation.newLookup()
                .from("third_system_Amazon_so_out_stock")
                .localField("shipmentItemId")
                .foreignField("shipmentItemId")
                .as("joinedResults");

        AggregationOperation filterStage = Aggregation.match(
                new Criteria().orOperator(
                        Criteria.where("joinedResults").size(0), // joinedResults 数组为空的情况
                        new Criteria().andOperator(
                                Criteria.where("shipmentItemId").exists(true),
                                Criteria.where("joinedResults.shipmentItemId").exists(false)
                        ), // shipmentItemId 存在，但不在 joinedResults.shipmentItemId 中
                        new Criteria().andOperator(
                                Criteria.where("joinedResults.shipmentItemId").exists(true),
                                Criteria.where("quantityShipped").ne("$joinedResults.quantityShipped")
                        ) // quantityShipped 不等于 joinedResults 中的 quantityShipped
                )
        );

        Aggregation aggregation = Aggregation.newAggregation(
                matchStage,
                lookupStage,
                filterStage,
                Aggregation.limit(size)
        );

        AggregationResults<ReportFulfilledShipmentsMongoDTO> results = mongoTemplate.aggregate(aggregation, "data_report_amz_fulfilled_shipments", ReportFulfilledShipmentsMongoDTO.class);
        return results.getMappedResults();
    }



